    lines.add('${categories[i]}: pod ${fraction(pod.$1,pod.$2)}, far ${fraction(far.$1,far.$2)}');
  }
  for (var b = 0; b<5; b++) {
    lines.add('hours ${b*6}-${b*6+5}: ${fraction(hits[b],pairs[b])}');
  }
  return [...lines, ...amendments];
}

